BOOKINGS=$t bash src/remind.sh --who >/dev/null 2>&1; [ $? = 2 ] || { echo "--who without a name should exit 2"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/remind.sh --who nobody 2026-01-01)" ] || { echo "--who with no bookings should print nothing"; fail=1; }
BOOKINGS=$t bash src/remind.sh --who nobody 2026-01-01 >/dev/null; [ $? = 0 ] || { echo "--who with no bookings should exit 0"; fail=1; }
rm -f "$t"; exit $fail

