#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list sorted"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "list by date"; fail=1; }
rm -f "$t"; exit $fail

spec/remind_who.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tsato\nkaede\t2026-01-01\t13:00\t14:00\tito\nsakura\t2026-01-01\t15:00\t16:00\tsatoh\n' > "$t"
[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01)" = 'reminder to sato: aoi 2026-01-01 10:00-11:00' ] || { echo "remind --who"; fail=1; }
bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01 | wc -l)" = 1 ] || { echo "--who matched a longer name"; fail=1; }
bash src/remind.sh --who >/dev/null 2>&1; [ $? = 2 ] || { echo "--who without a name should exit 2"; fail=1; }
out=$(BOOKINGS=$t bash src/remind.sh --who nobody 2026-01-01); rc=$?
[ -z "$out" ] && [ $rc = 0 ] || { echo "--who with no matching name should print nothing and exit 0"; fail=1; }
rm -f "$t"; exit $fail

